<script setup>import {useRouter} from 'vue-router';import {useAuth} from '../stores/auth';const router=useRouter(),auth=useAuth();const logout=()=>{auth.logout();router.push('/');};</script>
<template><section class="page"><template v-if="auth.user.value"><span>MEMBER PROFILE</span><h1>Hello, <em>{{auth.user.value.name}}.</em></h1><div class="card"><b>{{auth.user.value.name.charAt(0).toUpperCase()}}</b><div><small>EMAIL / USER ID</small><strong>{{auth.user.value.email}}</strong></div><div><small>INTERNAL ID</small><strong>{{auth.user.value.id}}</strong></div><div><small>MEMBER SINCE</small><strong>{{auth.user.value.createdAt}}</strong></div></div><div class="actions"><RouterLink class="solid-button" to="/products">Browse collection</RouterLink><button @click="logout">Logout</button></div></template><div v-else class="empty"><h1>You are not logged in.</h1><RouterLink class="solid-button" to="/login">Login</RouterLink></div></section></template>
<style scoped>.page{padding:74px 8vw}.page>span{color:var(--coral-dark);font-size:10px;font-weight:900;letter-spacing:.18em}h1{max-width:900px;margin:14px 0 40px;font:400 clamp(58px,7vw,94px)/.9 Georgia}h1 em{color:var(--forest);font-weight:400}.card{max-width:900px;padding:35px;display:grid;grid-template-columns:150px 1fr;gap:26px 34px;align-items:center;border-radius:30px;background:var(--cream)}.card>b{grid-row:1/4;width:125px;height:125px;display:grid;place-items:center;border-radius:50%;background:var(--coral);font:400 56px Georgia}.card div{display:grid;gap:5px}.card small{color:var(--muted);font-size:9px;font-weight:900;letter-spacing:.16em}.card strong{overflow-wrap:anywhere}.actions{margin-top:27px;display:flex;gap:12px}.actions button{padding:13px 18px;border:1px solid var(--line);border-radius:999px;background:transparent;color:#a63e2c;font-weight:900}.empty{text-align:center}@media(max-width:600px){.page{padding-inline:20px}.card{grid-template-columns:1fr}.card>b{grid-row:auto}}</style>
